package cli

import (
	"context"
	"encoding/csv"
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/spf13/cobra"
)

// reconcileRow represents one row of the local table compared against Catastro.
type reconcileRow struct {
	RC          string            `json:"rc"`
	Local       map[string]string `json:"local"`
	Catastro    map[string]any    `json:"catastro,omitempty"`
	Differences map[string][2]any `json:"differences,omitempty"`
	Error       string            `json:"error,omitempty"`
	Status      string            `json:"status"` // "match" | "drift" | "not_found" | "error"
}

func newReconcileCmd(flags *rootFlags) *cobra.Command {
	var (
		rcCol  string
		fields string
		report string
		csvIn  bool
	)
	cmd := &cobra.Command{
		Use:   "reconcile [FILE]",
		Short: "Compara una tabla local (CSV) de parcelas contra Catastro y reporta drift",
		Long: "Lee un fichero CSV con una columna 'rc' (o la columna nombrada con --rc-col) y, por cada\n" +
			"fila, llama a Consulta_DNPRC. Compara los campos declarados en --fields contra la respuesta\n" +
			"de Catastro y emite un informe JSONL con el drift. Exit code != 0 si encuentra mismatches.\n\n" +
			"Útil para auditar padrones de urbanizaciones contra la fuente oficial.",
		Example: "  catastro-pp-cli reconcile parcelas.csv --rc-col rc --fields surface,use,year --json",
		Annotations: map[string]string{
			"mcp:read-only":       "true",
			"pp:typed-exit-codes": "0,3",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			path := args[0]
			if dryRunOK(flags) {
				fmt.Fprintf(cmd.OutOrStdout(),
					`{"would_reconcile":%q,"rc_column":%q,"fields":%q}`+"\n",
					path, rcCol, fields)
				return nil
			}
			f, err := os.Open(path)
			if err != nil {
				return fmt.Errorf("open %s: %w", path, err)
			}
			defer f.Close()
			r := csv.NewReader(f)
			r.FieldsPerRecord = -1
			rows, err := r.ReadAll()
			if err != nil {
				return fmt.Errorf("parse CSV: %w", err)
			}
			if len(rows) < 2 {
				return fmt.Errorf("CSV needs at least a header and one data row")
			}
			header := rows[0]
			rcIdx := -1
			fieldIdxByName := map[string]int{}
			declaredFields := splitTrim(fields, ",")
			for i, h := range header {
				lower := strings.ToLower(strings.TrimSpace(h))
				if lower == rcCol {
					rcIdx = i
				}
				fieldIdxByName[lower] = i
			}
			if rcIdx == -1 {
				return fmt.Errorf("rc column %q not found in CSV header %v", rcCol, header)
			}

			c, err := flags.newClient()
			if err != nil {
				return err
			}

			ctx, cancel := context.WithTimeout(context.Background(), flags.timeout)
			defer cancel()
			_ = ctx

			results := []reconcileRow{}
			drifted := 0
			for _, row := range rows[1:] {
				rc := strings.TrimSpace(row[rcIdx])
				if rc == "" {
					continue
				}
				rr := reconcileRow{
					RC:    rc,
					Local: map[string]string{},
				}
				for _, fname := range declaredFields {
					if idx, ok := fieldIdxByName[fname]; ok && idx < len(row) {
						rr.Local[fname] = strings.TrimSpace(row[idx])
					}
				}
				data, err := c.Get("/COVCCallejero.svc/json/Consulta_DNPRC", map[string]string{"RefCat": rc})
				if err != nil {
					rr.Status = "error"
					rr.Error = err.Error()
					results = append(results, rr)
					drifted++
					continue
				}
				// Surface OVC API errors (cuerr>0 or lerr entries) as status=error.
				if apiErr := detectCatastroError(data); apiErr != "" {
					rr.Status = "error"
					rr.Error = apiErr
					results = append(results, rr)
					drifted++
					continue
				}
				// Parse and extract canonical fields
				cat := extractCatastroFields(data)
				rr.Catastro = cat
				rr.Differences = compareFields(rr.Local, cat, declaredFields)
				if len(rr.Differences) > 0 {
					rr.Status = "drift"
					drifted++
				} else if len(rr.Catastro) == 0 {
					rr.Status = "not_found"
					drifted++
				} else {
					rr.Status = "match"
				}
				results = append(results, rr)
			}

			// Output
			if flags.asJSON || !isTerminal(cmd.OutOrStdout()) {
				enc := json.NewEncoder(cmd.OutOrStdout())
				enc.SetIndent("", "  ")
				for _, r := range results {
					if err := enc.Encode(r); err != nil {
						return err
					}
				}
			} else {
				fmt.Fprintf(cmd.OutOrStdout(), "Reconciled %d rows: %d match, %d drift/missing/error\n",
					len(results), len(results)-drifted, drifted)
				for _, r := range results {
					if r.Status != "match" {
						fmt.Fprintf(cmd.OutOrStdout(), "  %s [%s]\n", r.RC, r.Status)
						for k, v := range r.Differences {
							fmt.Fprintf(cmd.OutOrStdout(), "    %s: %v → %v\n", k, v[0], v[1])
						}
					}
				}
			}

			if report != "" {
				f, ferr := os.Create(report)
				if ferr == nil {
					enc := json.NewEncoder(f)
					enc.SetIndent("", "  ")
					for _, r := range results {
						_ = enc.Encode(r)
					}
					f.Close()
				}
			}

			if drifted > 0 {
				return &cliError{code: 3, err: fmt.Errorf("found drift in %d rows of %d", drifted, len(results))}
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&rcCol, "rc-col", "rc", "Nombre de la columna que contiene la referencia catastral")
	cmd.Flags().StringVar(&fields, "fields", "surface,use,year,address", "Lista de campos a comparar (separados por coma)")
	cmd.Flags().StringVar(&report, "report", "", "Ruta opcional para escribir el informe JSONL completo")
	cmd.Flags().BoolVar(&csvIn, "csv", false, "Forzar input CSV (autodetectado por extensión)")
	_ = time.Second // keep import
	return cmd
}

func splitTrim(s, sep string) []string {
	parts := strings.Split(s, sep)
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if p != "" {
			out = append(out, strings.ToLower(p))
		}
	}
	return out
}

// extractCatastroFields takes the raw Consulta_DNPRC JSON and projects a flat
// map of high-gravity fields. Catastro wraps the response in
// consulta_dnprcResult.bico, so we walk that structure.
// detectCatastroError inspects an OVC JSON response and returns a non-empty
// error description if Catastro signaled an error (cuerr>0 with lerr entries).
// Returns "" when the response looks clean.
func detectCatastroError(data json.RawMessage) string {
	var v map[string]any
	if err := json.Unmarshal(data, &v); err != nil {
		return ""
	}
	flat := map[string]any{}
	flatten(v, "", flat)
	cuerr, _ := flat["control.cuerr"].(float64)
	if cuerr > 0 {
		cod, _ := flat["lerr.0.cod"].(string)
		des, _ := flat["lerr.0.des"].(string)
		if cod != "" || des != "" {
			return fmt.Sprintf("OVC error %s: %s", cod, des)
		}
	}
	// Walk envelope keys too
	for k := range v {
		if inner, ok := v[k].(map[string]any); ok {
			inner2 := map[string]any{}
			flatten(inner, "", inner2)
			if e, _ := inner2["control.cuerr"].(float64); e > 0 {
				cod, _ := inner2["lerr.0.cod"].(string)
				des, _ := inner2["lerr.0.des"].(string)
				if cod != "" || des != "" {
					return fmt.Sprintf("OVC error %s: %s", cod, des)
				}
			}
		}
	}
	return ""
}

func extractCatastroFields(data json.RawMessage) map[string]any {
	out := map[string]any{}
	var envelope map[string]json.RawMessage
	if err := json.Unmarshal(data, &envelope); err != nil {
		return out
	}
	// Try to find the bico (bienes inmuebles) section
	var inner json.RawMessage
	for _, key := range []string{"consulta_dnprcResult", "Consulta_DNPRCResult"} {
		if v, ok := envelope[key]; ok {
			inner = v
			break
		}
	}
	if inner == nil {
		return out
	}
	var bico map[string]any
	if err := json.Unmarshal(inner, &bico); err != nil {
		return out
	}
	// Try multiple paths Catastro is known to use
	if v, ok := bico["bi"]; ok {
		flatten(v, "", out)
	} else if v, ok := bico["bico"]; ok {
		flatten(v, "", out)
	} else {
		flatten(bico, "", out)
	}

	// Normalize known fields
	norm := map[string]any{}
	for k, v := range out {
		lk := strings.ToLower(k)
		// Surface
		if strings.Contains(lk, "sfc") || strings.Contains(lk, "superficie") {
			norm["surface"] = v
		}
		// Use
		if strings.Contains(lk, "luso") || strings.Contains(lk, "uso") {
			norm["use"] = v
		}
		// Built year
		if strings.Contains(lk, "ant") || strings.Contains(lk, "year") || strings.Contains(lk, "ano_") || strings.Contains(lk, "ano") {
			norm["year"] = v
		}
		// Address
		if strings.Contains(lk, "ldt") || strings.Contains(lk, "dir") {
			norm["address"] = v
		}
	}
	// Keep both: original keys for transparency + normalized
	for k, v := range norm {
		out[k] = v
	}
	return out
}

func flatten(v any, prefix string, out map[string]any) {
	switch t := v.(type) {
	case map[string]any:
		for k, sub := range t {
			key := k
			if prefix != "" {
				key = prefix + "." + k
			}
			flatten(sub, key, out)
		}
	case []any:
		for i, sub := range t {
			flatten(sub, fmt.Sprintf("%s.%d", prefix, i), out)
		}
	default:
		out[prefix] = v
	}
}

func compareFields(local map[string]string, cat map[string]any, fields []string) map[string][2]any {
	out := map[string][2]any{}
	for _, f := range fields {
		lv, hasLocal := local[f]
		cv, hasCat := cat[f]
		if !hasCat {
			continue // can't compare what we don't have
		}
		cs := fmt.Sprintf("%v", cv)
		if hasLocal && strings.EqualFold(strings.TrimSpace(lv), strings.TrimSpace(cs)) {
			continue
		}
		out[f] = [2]any{lv, cs}
	}
	return out
}
